cd /opt/nxeon && node -e '
const SRC_WRITE_RE = /(?:^|[\n|;&`]\s*)(?:rm|rmdir|mv|shred|mkfs\S*|mkswap|parted|fdisk|chmod|chown|useradd|userdel|passwd|shutdown|reboot|halt|poweroff|init\s+[06])\b|(?:^|[\n|;&`]\s*)dd\s[^\n|;&`]*\bof=\/dev\/(?:sd|nvme|vd|xvd|hd|mapper)/i;
const lines=[
"export LC_ALL=C",
`if command -v timeout >/dev/null 2>&1; then TO="timeout 25"; else TO=""; fi`,
`awk -F: \x27($3>=1000 && $3<65534){printf "PWUSER\\t%s\\t%s\\t%s\\t%s\\t%s\\n",$1,$3,$4,$6,$7}\x27 /etc/passwd 2>/dev/null | head -n 40`,
`  for crf in "$crd"/*; do`,
`docker inspect "$cid" --format "$FMT"`,
];
const g=new RegExp(SRC_WRITE_RE.source,"gi");
for(const l of lines){const m=l.match(g);console.log(JSON.stringify(l.slice(0,70)),"=>",m);}
// now test whole joined multi-line with pipe-anchor. Build a representative snippet:
const snip=`  $TO grep -hE \x27^[[:space:]]*server_name[[:space:]]+[^;]+;\x27 $ngf 2>/dev/null | head -n 80 | while IFS= read -r sl; do`;
console.log("grep line:", snip.match(g));
'

cd /opt/nxeon && ls -la migration-source-audit.log 2>/dev/null && node -e '
const fs=require("fs");
const SRC_WRITE_RE = /(?:^|[\n|;&`]\s*)(?:rm|rmdir|mv|shred|mkfs\S*|mkswap|parted|fdisk|chmod|chown|useradd|userdel|passwd|shutdown|reboot|halt|poweroff|init\s+[06])\b|(?:^|[\n|;&`]\s*)dd\s[^\n|;&`]*\bof=\/dev\/(?:sd|nvme|vd|xvd|hd|mapper)/i;
const lines=fs.readFileSync("migration-source-audit.log","utf8").split("\n").filter(Boolean);
console.log("audit lines:",lines.length);
let hit=0;
for(const l of lines){ if(SRC_WRITE_RE.test(l)){hit++; if(hit<=3){const m=l.match(SRC_WRITE_RE); const idx=l.search(SRC_WRITE_RE); console.log("MATCH @",idx,"->",JSON.stringify(l.slice(Math.max(0,idx-15),idx+25))); }}}
console.log("total matching audit lines:",hit);
' 2>&1 | head -40

cd /opt/nxeon && sed -n '1003,1185p' worker/migrate-real.ts > /tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/inv.txt 2>/dev/null; node -e '
const fs=require("fs");
// Reconstruct the array values by evaluating the TS array literal region loosely.
const src=fs.readFileSync("/opt/nxeon/worker/migrate-real.ts","utf8");
const m=src.match(/export function srcInventoryScript\(priv: string\): string \{\s*return \[([\s\S]*?)\]\.join\("\\n"\);/);
if(!m){console.log("no match region");process.exit(1);}
// Evaluate the array literal with priv="" 
const arrLit="["+m[1]+"]";
const priv="";
let arr;
try{ arr=eval(arrLit.replace(/priv/g,JSON.stringify(priv))); }catch(e){console.log("eval err",e.message);process.exit(1);}
const script=arr.join("\n");
const SRC_WRITE_RE = /(?:^|[\n|;&`]\s*)(?:rm|rmdir|mv|shred|mkfs\S*|mkswap|parted|fdisk|chmod|chown|useradd|userdel|passwd|shutdown|reboot|halt|poweroff|init\s+[06])\b|(?:^|[\n|;&`]\s*)dd\s[^\n|;&`]*\bof=\/dev\/(?:sd|nvme|vd|xvd|hd|mapper)/i;
console.log("guard trips?",SRC_WRITE_RE.test(script));
const idx=script.search(SRC_WRITE_RE);
console.log("match at index",idx);
console.log("context:",JSON.stringify(script.slice(Math.max(0,idx-40),idx+40)));
'

cd /opt/nxeon && node -e '
const fs=require("fs");
const all=fs.readFileSync("worker/migrate-real.ts","utf8").split("\n");
// lines are 1-indexed; array body 1003..1184 (before ].join)
const body=all.slice(1002,1184);
const parts=[];
for(let raw of body){
  let t=raw.trim();
  if(t.startsWith("//")) continue;
  if(t==="") continue;
  // strip trailing comma
  if(t.endsWith(",")) t=t.slice(0,-1);
  if(!(t.startsWith("\x27")||t.startsWith("\x22"))) { continue; }
  try{ parts.push(eval("("+t.replace(/\x27 \+ priv \+ \x27/g,"")+")")); }
  catch(e){ /* handle concatenations like PRIV=" + priv + " */ 
    try{ const withPriv=t.replace(/priv/g,"\x22\x22"); parts.push(eval("("+withPriv+")")); }catch(e2){ console.log("skip:",t.slice(0,40)); }
  }
}
const script=parts.join("\n");
const SRC_WRITE_RE = /(?:^|[\n|;&`]\s*)(?:rm|rmdir|mv|shred|mkfs\S*|mkswap|parted|fdisk|chmod|chown|useradd|userdel|passwd|shutdown|reboot|halt|poweroff|init\s+[06])\b|(?:^|[\n|;&`]\s*)dd\s[^\n|;&`]*\bof=\/dev\/(?:sd|nvme|vd|xvd|hd|mapper)/i;
console.log("parts:",parts.length,"trips?",SRC_WRITE_RE.test(script));
const g=new RegExp(SRC_WRITE_RE.source,"gi");
let m; while((m=g.exec(script))){ const i=m.index; console.log("MATCH:",JSON.stringify(script.slice(Math.max(0,i-30),i+30))); if(g.lastIndex===i)g.lastIndex++; }
'

