  // `ok` when that status means "killed" rather than "no matches". `timeout`
  // reports 124/137; `xargs` reports 125 when its child died on a signal; 126/127
  // are "could not run it at all". `xargs` reports 123 when grep merely exited 1
  // (no matches), which is the ordinary clean case and must NOT clear `ok`.
  const pass = (kind: string, grepArgs: string) => [
    "  echo 0 > \"$RC\"",
    `  ( $TO xargs -0 -r grep -I -H -n -o ${grepArgs} -- < "$LIST" 2>/dev/null; echo $? > "$RC" ) | head -n ${SWEEP_MAX_HITS} | while IFS= read -r hl; do`,
    `    printf '${kind}\\t%s\\n' "$hl"`,
    "  done",
    '  rc=$(cat "$RC" 2>/dev/null); [ -n "$rc" ] || rc=0',
    '  case "$rc" in 124|125|126|127|13[0-9]|14[0-9]) ok=0 ;; esac',
